package info.deltaindices.volumecamera;
import android.content.*;import android.net.Uri;import androidx.annotation.NonNull;import androidx.work.Worker;import androidx.work.WorkerParameters;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public final class DriveUploadWorker extends Worker {
 public DriveUploadWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);}
 @NonNull @Override public Result doWork(){Context c=getApplicationContext();String token=Settings.driveToken(c);if(token==null){DriveSync.failed(c,"Connect Google Drive to sync pending pictures",false);return Result.failure();}JSONObject item=DriveSync.first(c);if(item==null)return Result.success();try{String folder=ensureFolder(token,Settings.driveFolder(c));upload(token,folder,Uri.parse(item.getString("uri")),item.getString("name"));DriveSync.success(c);if(DriveSync.pending(c)>0)DriveSync.schedule(c);return Result.success();}catch(AuthRequired e){Settings.prefs(c).edit().putBoolean(Settings.DRIVE_AUTH_REQUIRED,true).apply();DriveSync.failed(c,"Google Drive reconnect required",false);return Result.failure();}catch(Exception e){DriveSync.failed(c,"Waiting to retry Drive sync: "+e.getClass().getSimpleName(),false);return Result.retry();}}
 private String ensureFolder(String token,String name)throws Exception{String saved=Settings.prefs(getApplicationContext()).getString(Settings.DRIVE_FOLDER_ID,null);if(saved!=null)return saved;String escaped=name.replace("\\","\\\\").replace("'","\\'");HttpURLConnection find=open("https://www.googleapis.com/drive/v3/files?spaces=drive&pageSize=1&fields=files(id,name)&q="+URLEncoder.encode("mimeType='application/vnd.google-apps.folder' and name='"+escaped+"' and trashed=false","UTF-8"),"GET",token);String body=response(find);JSONArray files=new JSONObject(body).getJSONArray("files");String id;if(files.length()>0)id=files.getJSONObject(0).getString("id");else{HttpURLConnection create=open("https://www.googleapis.com/drive/v3/files?fields=id","POST",token);create.setRequestProperty("Content-Type","application/json; charset=UTF-8");write(create,new JSONObject().put("name",name).put("mimeType","application/vnd.google-apps.folder").toString().getBytes(StandardCharsets.UTF_8));id=new JSONObject(response(create)).getString("id");}Settings.prefs(getApplicationContext()).edit().putString(Settings.DRIVE_FOLDER_ID,id).apply();return id;}
 private void upload(String token,String folder,Uri uri,String name)throws Exception{String boundary="dli-"+System.nanoTime();HttpURLConnection c=open("https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id","POST",token);c.setRequestProperty("Content-Type","multipart/related; boundary="+boundary);c.setChunkedStreamingMode(256*1024);try(OutputStream out=c.getOutputStream();InputStream in=getApplicationContext().getContentResolver().openInputStream(uri)){String metadata="--"+boundary+"\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n"+new JSONObject().put("name",name).put("parents",new JSONArray().put(folder))+"\r\n--"+boundary+"\r\nContent-Type: image/jpeg\r\n\r\n";out.write(metadata.getBytes(StandardCharsets.UTF_8));if(in==null)throw new FileNotFoundException(uri.toString());byte[] buffer=new byte[65536];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);out.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));}response(c);}
 private HttpURLConnection open(String url,String method,String token)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod(method);c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setRequestProperty("Authorization","Bearer "+token);c.setDoOutput("POST".equals(method));return c;}
 private void write(HttpURLConnection c,byte[] value)throws Exception{try(OutputStream out=c.getOutputStream()){out.write(value);}}
 private String response(HttpURLConnection c)throws Exception{int code=c.getResponseCode();InputStream stream=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(stream!=null){byte[] buffer=new byte[8192];int count;while((count=stream.read(buffer))!=-1)bytes.write(buffer,0,count);stream.close();}String body=bytes.toString(StandardCharsets.UTF_8.name());if(code==401||code==403)throw new AuthRequired();if(code<200||code>=300)throw new IOException("Drive HTTP "+code+" "+body);return body;}
 private static final class AuthRequired extends Exception{}
}
